'use strict';

// MODULES //

var logger = require( 'debug' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:diagnostic' );


// MAIN //

/**
* Appends a diagnostic to a conversion state.
*
* @private
* @param {Object} state - conversion state
* @param {string} severity - diagnostic severity
* @param {string} code - diagnostic code
* @param {string} message - diagnostic message
* @param {Object} [node] - source MDAST node
* @param {Object} [details] - diagnostic details
* @returns {Object} diagnostic
*/
function diagnostic( state, severity, code, message, node, details ) {
	// Namespace diagnostic codes at creation time and always attach a source object. An empty source reference list denotes a document-level rather than node-level issue:
	var out = {
		'severity': severity,
		'code': format( 'semantic-document/%s', code ),
		'message': message,
		'source': state.provenance.source( ( node ) ? [ node ] : [] ),
		'details': details || {}
	};
	state.document.diagnostics.push( out );
	debug( 'Appended diagnostic: severity=%s code=%s sourceRefs=%d', severity, out.code, out.source.refs.length );
	return out;
}


// EXPORTS //

module.exports = diagnostic;
